export class PageLoad{id;url;startTime;loadTime;contentLoadTime;mainRequest;constructor(e){this.id=++PageLoad.lastIdentifier,this.url=e.url(),this.startTime=e.startTime,this.mainRequest=e}static forRequest(e){return pageLoadForRequest.get(e)||null}bindRequest(e){pageLoadForRequest.set(e,this)}static lastIdentifier=0}const pageLoadForRequest=new WeakMap;